-- Add 24 editable practice exams, ten questions per exam, without altering historical demo exams.
-- Requires sample-data.sql first. Sequential reruns insert only missing natural keys.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
CREATE TEMPORARY TABLE examguard_practice_items (
    subject_number INT NOT NULL,
    question_number INT NOT NULL,
    content TEXT NOT NULL,
    type VARCHAR(20) NOT NULL,
    difficulty VARCHAR(10) NOT NULL,
    option_1 TEXT, option_2 TEXT, option_3 TEXT, option_4 TEXT,
    correct_order INT,
    PRIMARY KEY (subject_number, question_number)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;
SELECT s.id, u.id, i.content, i.type, i.difficulty, TRUE
FROM examguard_practice_items i
JOIN subjects s ON s.code = CONCAT('DEMO-SUB-', LPAD(i.subject_number, 2, '0'))
JOIN users u ON u.username = CONCAT('demo_teacher', LPAD(1 + MOD(i.subject_number - 1, 3), 2, '0'))
WHERE i.question_number > 0
AND NOT EXISTS (SELECT 1 FROM questions q WHERE q.subject_id = s.id AND q.created_by = u.id AND q.content = i.content);

SELECT q.id, CASE o.n WHEN 1 THEN i.option_1 WHEN 2 THEN i.option_2 WHEN 3 THEN i.option_3 ELSE i.option_4 END,
       o.n = i.correct_order, o.n
FROM examguard_practice_items i
JOIN subjects s ON s.code = CONCAT('DEMO-SUB-', LPAD(i.subject_number, 2, '0'))
JOIN users u ON u.username = CONCAT('demo_teacher', LPAD(1 + MOD(i.subject_number - 1, 3), 2, '0'))
JOIN questions q ON q.subject_id = s.id AND q.created_by = u.id AND q.content = i.content
CROSS JOIN (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4) o
WHERE i.question_number > 0 AND q.type = 'SINGLE_CHOICE'
AND NOT EXISTS (SELECT 1 FROM question_options existing WHERE existing.question_id = q.id AND existing.display_order = o.n);

                  duration_minutes, max_attempts, shuffle_questions, shuffle_options, result_visibility)
SELECT s.id, u.id, CONCAT('Đề thực hành 10 câu - ', s.name), 'EXAMGUARD_PRACTICE_V1', 'DRAFT', NULL, NULL,
       45, 3, TRUE, TRUE, 'AFTER_EXAM_END'
FROM (SELECT DISTINCT subject_number FROM examguard_practice_items) i
JOIN subjects s ON s.code = CONCAT('DEMO-SUB-', LPAD(i.subject_number, 2, '0'))
JOIN users u ON u.username = CONCAT('demo_teacher', LPAD(1 + MOD(i.subject_number - 1, 3), 2, '0'))
WHERE NOT EXISTS (SELECT 1 FROM exams e WHERE e.subject_id = s.id AND e.description = 'EXAMGUARD_PRACTICE_V1');

SELECT e.id, c.id FROM exams e
JOIN subjects s ON s.id = e.subject_id
JOIN classes c ON c.code = REPLACE(s.code, 'DEMO-SUB-', 'DEMO-CLS-') AND c.teacher_id = e.teacher_id
WHERE e.description = 'EXAMGUARD_PRACTICE_V1' AND e.status = 'DRAFT'
AND NOT EXISTS (SELECT 1 FROM exam_classes ec WHERE ec.exam_id = e.id AND ec.class_id = c.id)
AND NOT EXISTS (SELECT 1 FROM exam_sessions es WHERE es.exam_id = e.id);

SELECT e.id, q.id, 1.00, i.question_number + 1
FROM examguard_practice_items i
JOIN subjects s ON s.code = CONCAT('DEMO-SUB-', LPAD(i.subject_number, 2, '0'))
JOIN exams e ON e.subject_id = s.id AND e.description = 'EXAMGUARD_PRACTICE_V1'
JOIN questions q ON q.subject_id = s.id AND q.created_by = e.teacher_id AND q.content = i.content
WHERE e.status = 'DRAFT'
AND NOT EXISTS (SELECT 1 FROM exam_sessions es WHERE es.exam_id = e.id)
AND NOT EXISTS (SELECT 1 FROM exam_questions eq WHERE eq.exam_id = e.id AND (eq.question_id = q.id OR eq.display_order = i.question_number + 1));
COMMIT;
DROP TEMPORARY TABLE examguard_practice_items;
